export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-14\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 14,\n    \"title\": \"奸劫弒臣\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 13,\n    \"passageIds\": [\n      \"han-fei-zi_ch-14_p-1\",\n      \"han-fei-zi_ch-14_p-2\",\n      \"han-fei-zi_ch-14_p-3\",\n      \"han-fei-zi_ch-14_p-4\",\n      \"han-fei-zi_ch-14_p-5\",\n      \"han-fei-zi_ch-14_p-6\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"order\": 1,\n      \"canonicalText\": \"凡姦臣皆欲順人主之心以取親幸之勢者也。是以主有所善，臣從而譽之；主有所憎，臣因而毀之。凡人之大體，取捨同者則相是也，取捨異者則相非也。今人臣之所譽者，人主之所是也，此之謂同取。人臣之所毀者，人主之所非也，此之謂同舍。夫取捨合而相與逆者，未嘗聞也，此人臣之所以取信幸之道也。夫姦臣得乘信幸之勢以毀譽進退群臣者，人主非有術數以御之也，非參驗以審之也，必將以曩之合己信今之言，此倖臣之所以得欺主成私者也。故主必欺於上，而臣必重於下矣，此之謂擅主之臣。國有擅主之臣，則羣下不得盡其智力以陳其忠，百官之吏不得奉法以致其功矣。何以明之？夫安利者就之，危害者去之，此人之情也。今為臣盡力以致功，竭智以陳忠者，其身困而家貧，父子罹其害；為姦利以弊人主，行財貨以事貴重之臣者，身尊家富，父子被其澤；人焉能去安利之道而就危害之處哉？治國若此其過也，而上欲下之無姦，吏之奉法，其不可得亦明矣。故左右知貞信之不可以得安利也，必曰：「我以忠信事上積功勞而求安，是猶盲而欲知黑白之情，必不幾矣。若以道化行正理不趨富貴事上而求安，是猶聾而欲審清濁之聲也，愈不幾矣。二者不可以得安，我安能無相比周、蔽主上、為姦私以適重人哉？」此必不顧人主之義矣。其百官之吏，亦知方正之不可以得安也，必曰：「我以清廉事上而求安，若無規矩而欲為方圓也，必不幾矣。若以守法不朋黨治官而求安，是猶以足搔頂也，愈不幾也。二者不可以得安，能無廢法行私以適重人哉？」此必不顧君上之法矣。故以私為重人者眾，而以法事君者少矣。是以主孤於上而臣成黨於下，此田成之所以弒簡公者也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-14_p-1_s-1\",\n        \"han-fei-zi_ch-14_p-1_s-2\",\n        \"han-fei-zi_ch-14_p-1_s-3\",\n        \"han-fei-zi_ch-14_p-1_s-4\",\n        \"han-fei-zi_ch-14_p-1_s-5\",\n        \"han-fei-zi_ch-14_p-1_s-6\",\n        \"han-fei-zi_ch-14_p-1_s-7\",\n        \"han-fei-zi_ch-14_p-1_s-8\",\n        \"han-fei-zi_ch-14_p-1_s-9\",\n        \"han-fei-zi_ch-14_p-1_s-10\",\n        \"han-fei-zi_ch-14_p-1_s-11\",\n        \"han-fei-zi_ch-14_p-1_s-12\",\n        \"han-fei-zi_ch-14_p-1_s-13\",\n        \"han-fei-zi_ch-14_p-1_s-14\",\n        \"han-fei-zi_ch-14_p-1_s-15\",\n        \"han-fei-zi_ch-14_p-1_s-16\",\n        \"han-fei-zi_ch-14_p-1_s-17\",\n        \"han-fei-zi_ch-14_p-1_s-18\",\n        \"han-fei-zi_ch-14_p-1_s-19\",\n        \"han-fei-zi_ch-14_p-1_s-20\",\n        \"han-fei-zi_ch-14_p-1_s-21\",\n        \"han-fei-zi_ch-14_p-1_s-22\",\n        \"han-fei-zi_ch-14_p-1_s-23\",\n        \"han-fei-zi_ch-14_p-1_s-24\",\n        \"han-fei-zi_ch-14_p-1_s-25\",\n        \"han-fei-zi_ch-14_p-1_s-26\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"凡姦臣屬皆欲順人主的心以取親幸的權位威勢的人或事啊。是以主有所善，臣屬從而且譽的；主有所憎，臣屬因而且毀的。凡人的大體，取捨同的人或事則相是啊，取捨異的人或事則相絕不是啊。今人臣屬的所譽的人或事，人主的所是啊，此的謂同取。人臣屬的所毀的人或事，人主的所絕不是啊，此的謂同舍。夫取捨合而且相與逆的人或事，未嘗聞啊，此人臣屬的所以取信幸的道啊。夫姦臣屬得乘信幸的權位威勢以毀譽進退群臣屬的人或事，人主絕不是有督察權術數以御的啊，絕不是參驗以審的啊，必將以曩的合己信今的言，此倖臣屬的所以得欺主成私的人或事啊。所以主必欺於上，而且臣屬必重於下矣，此的謂擅主的臣屬。國有擅主的臣屬，則羣下不得盡他的智力以陳他的忠，百官的吏不得奉法規法令以致他的功矣。何以明的？夫安利的人或事就的，危害的人或事去的，此人的情啊。今為臣屬盡力以致功，竭智以陳忠的人或事，他的身困而且家貧，父子罹他的害；為姦利以弊人主，行財貨以事貴重的臣屬的人或事，身尊家富，父子被他的澤；人焉能去安利的道而且就危害的處哉？治國若此他的過啊，而且上欲下的無姦，吏的奉法規法令，他的不可得亦明矣。所以左右知貞信的不可以得安利啊，必說道：我以忠信事上積功勞而且求安，是猶盲而且欲知黑白的情，必不幾矣。若以道化行正理不趨富貴事上而且求安，是猶聾而且欲審清濁的聲啊，愈不幾矣。二的人或事不可以得安，我安能無相比周、蔽主上、為姦私以適重人哉？此必不顧人主的義矣。他的百官的吏，亦知方正的不可以得安啊，必說道：我以清廉事上而且求安，若無規矩而且欲為方圓啊，必不幾矣。若以守法規法令不朋黨治官而且求安，是猶以足搔頂啊，愈不幾啊。二的人或事不可以得安，能無廢法規法令行私以適重人哉？此必不顧國君上的法規法令矣。所以以私為重人的人或事眾，而且以法規法令事國君的人或事少矣。是以主孤於上而且臣屬成黨於下，此田成的所以弒簡公的人或事啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈奸劫弒臣〉。韓非深刻融合法、術、勢三大治國精要，此處「凡姦臣皆欲順人主之心以取親幸之勢者也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「凡」、「姦」、「臣」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「凡姦臣皆欲順人主之心以取親幸之勢者也是以主有所善」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「是以主有所善，臣從而譽之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"order\": 2,\n      \"canonicalText\": \"夫有術者之為人臣也，得效度數之言，上明主法，下困姦臣，以尊主安國者也。是以度數之言得效於前，則賞罰必用於後矣。人主誠明於聖人之術，而不苟於世俗之言，循名實而定是非，因參驗而審言辭。是以左右近習之臣，知偽詐之不可以得安也，必曰：「我不去姦私之行盡力竭智以事主，而乃以相與比周妄毀譽以求安，是猶負千鈞之重，陷於不測之淵而求生也，必不幾矣。」百官之吏，亦知為姦利之不可以得安也，必曰：「我不以清廉方正奉法，乃以貪污之心枉法以取私利，是猶上高陵之顛，墮峻谿之下而求生，必不幾矣。」安危之道若此其明也，左右安能以虛言惑主，而百官安敢以貪漁下？是以臣得陳其忠而不弊，下得守其職而不怨。此管仲之所以治齊，而商君之所以強秦也。從是觀之，則聖人之治國也，固有使人不得不愛我之道，而不恃人之以愛為我也。恃人之以愛為我者危矣，恃吾不可不為者安矣。夫君臣非有骨肉之親，正直之道可以得利，則臣盡力以事主；正直之道不可以得安，則臣行私以幹上。明主知之，故設利害之道以示天下而已矣。夫是以人主雖不口教百官，不目索姦邪，而國已治矣。人主者，非目若離婁乃為明也，非耳若師曠乃為聰也。目必，不任其數，而待目以為明，所見者少矣，非不弊之術也。耳必，不因其勢，而待耳以為聰，所聞者寡矣，非不欺之道也。明主者，使天下不得不為己視，天下不得不為己聽。故身在深宮之中而明照四海之內，而天下弗能蔽、弗能欺者何也？闇亂之道廢，而聰明之勢興也。故善任勢者國安，不知因其勢者國危。古秦之俗，君臣廢法而服私，是以國亂兵弱而主卑。商君說秦孝公以變法易俗而明公道，賞告姦，困末作而利本事。當此之時，秦民習故俗之有罪可以得免、無功可以得尊顯也，故輕犯新法。於是犯之者其誅重而必，告之者其賞厚而信，故姦莫不得而被刑者眾，民疾怨而眾過日聞。孝公不聽，遂行商君之法，民後知有罪之必誅，而私姦者眾也，故民莫犯，其刑無所加。是以國治而兵強，地廣而主尊。此其所以然者，匿罪之罰重，而告姦之賞厚也。此亦使天下必為己視聽之道也。至治之法術已明矣，而世學者弗知也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-14_p-2_s-1\",\n        \"han-fei-zi_ch-14_p-2_s-2\",\n        \"han-fei-zi_ch-14_p-2_s-3\",\n        \"han-fei-zi_ch-14_p-2_s-4\",\n        \"han-fei-zi_ch-14_p-2_s-5\",\n        \"han-fei-zi_ch-14_p-2_s-6\",\n        \"han-fei-zi_ch-14_p-2_s-7\",\n        \"han-fei-zi_ch-14_p-2_s-8\",\n        \"han-fei-zi_ch-14_p-2_s-9\",\n        \"han-fei-zi_ch-14_p-2_s-10\",\n        \"han-fei-zi_ch-14_p-2_s-11\",\n        \"han-fei-zi_ch-14_p-2_s-12\",\n        \"han-fei-zi_ch-14_p-2_s-13\",\n        \"han-fei-zi_ch-14_p-2_s-14\",\n        \"han-fei-zi_ch-14_p-2_s-15\",\n        \"han-fei-zi_ch-14_p-2_s-16\",\n        \"han-fei-zi_ch-14_p-2_s-17\",\n        \"han-fei-zi_ch-14_p-2_s-18\",\n        \"han-fei-zi_ch-14_p-2_s-19\",\n        \"han-fei-zi_ch-14_p-2_s-20\",\n        \"han-fei-zi_ch-14_p-2_s-21\",\n        \"han-fei-zi_ch-14_p-2_s-22\",\n        \"han-fei-zi_ch-14_p-2_s-23\",\n        \"han-fei-zi_ch-14_p-2_s-24\",\n        \"han-fei-zi_ch-14_p-2_s-25\",\n        \"han-fei-zi_ch-14_p-2_s-26\",\n        \"han-fei-zi_ch-14_p-2_s-27\",\n        \"han-fei-zi_ch-14_p-2_s-28\",\n        \"han-fei-zi_ch-14_p-2_s-29\",\n        \"han-fei-zi_ch-14_p-2_s-30\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"夫有督察權術的人或事的為人臣屬啊，得效度數的言，上明主法規法令，下困姦臣屬，以尊主安國的人或事啊。是以度數的言得效於前，則賞賜與刑罰必用於後矣。人主誠明於聖人的督察權術，而且不苟於世俗的言，循名實而且定是絕不是，因參驗而且審言辭。是以左右近習的臣屬，知偽詐的不可以得安啊，必說道：我不去姦私的行盡力竭智以事主，而且乃以相與比周妄毀譽以求安，是猶負千鈞的重，陷於不測的淵而且求生啊，必不幾矣。百官的吏，亦知為姦利的不可以得安啊，必說道：我不以清廉方正奉法規法令，乃以貪污的心枉法規法令以取私利，是猶上高陵的顛，墮峻谿的下而且求生，必不幾矣。安危的道若此他的明啊，左右安能以虛言惑主，而且百官安敢以貪漁下？是以臣屬得陳他的忠而且不弊，下得守他的職而且不怨。此管仲的所以治齊，而且商國君的所以強秦啊。從是觀的，則聖人的治國啊，固有使人不得不愛我的道，而且不恃人的以愛為我啊。恃人的以愛為我的人或事危矣，恃吾不可不為的人或事安矣。夫國君臣屬絕不是有骨肉的親，正直的道可以得利，則臣屬盡力以事主；正直的道不可以得安，則臣屬行私以幹上。明主知的，所以設利害的道以示天下而且已矣。夫是以人主雖不口教百官，不目索姦邪，而且國已治矣。人主的人或事，絕不是目若離婁乃為明啊，絕不是耳若師曠乃為聰啊。目必，不任他的數，而且待目以為明，所見的人或事少矣，絕不是不弊的督察權術啊。耳必，不因他的權位威勢，而且待耳以為聰，所聞的人或事寡矣，絕不是不欺的道啊。明主的人或事，使天下不得不為己視，天下不得不為己聽。所以身在深宮的中而且明照四海的內，而且天下弗能蔽、弗能欺的人或事何啊？闇亂的道廢，而且聰明的權位威勢興啊。所以善任權位威勢的人或事國安，不知因他的權位威勢的人或事國危。古秦的俗，國君臣屬廢法規法令而且服私，是以國亂兵弱而且主卑。商國君說秦孝公以變法規法令易俗而且明公道，賞賜告姦，困末作而且利本事。當此的時，秦民習所以俗的有罪可以得免、無功可以得尊顯啊，所以輕犯新法規法令。於是犯的的人或事他的誅重而且必，告的的人或事他的賞賜厚而且信，所以姦莫不得而且被刑的人或事眾，民疾怨而且眾過日聞。孝公不聽，遂行商國君的法規法令，民後知有罪的必誅，而且私姦的人或事眾啊，所以民莫犯，他的刑無所加。是以國治而且兵強，地廣而且主尊。此他的所以然的人或事，匿罪的刑罰重，而且告姦的賞賜厚啊。此亦使天下必為己視聽的道啊。至治的法規法令督察權術已明矣，而且世學的人或事弗知啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈奸劫弒臣〉。韓非深刻融合法、術、勢三大治國精要，此處「夫有術者之為人臣也，得效度數之言，上明主法，下困姦臣，以尊主安國者也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「有」、「術」、「為」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「夫有術者之為人臣也得效度數之言上明主法下困姦臣以」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「是以度數之言得效於前，則賞罰必用於後矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"order\": 3,\n      \"canonicalText\": \"且夫世之愚學，皆不知治亂之情，讘䛟多誦先古之書，以亂當世之治；智慮不足以避阱井之陷，又妄非有術之士。聽其言者危，用其計者亂，此亦愚之至大，而患之至甚者也。俱與有術之士，有談說之名，而實相去千萬也，此夫名同而實有異者也。夫世愚學之人比有術之士也，猶螘垤之比大陵也，其相去遠矣。而聖人者，審於是非之實，察於治亂之情也。故其治國也，正明法，陳嚴刑，將以救羣生之亂，去天下之禍，使強不陵弱，眾不暴寡，耆老得遂，幼孤得長，邊境不侵，君臣相親，父子相保，而無死亡係虜之患，此亦功之至厚者也。愚人不知，顧以為暴。愚者固欲治而惡其所以治，皆惡危而喜其所以危者。何以知之？夫嚴刑重罰者，民之所惡也，而國之所以治也；哀憐百姓、輕刑罰者，民之所喜，而國之所以危也。聖人為法國者，必逆於世，而順於道德。知之者，同於義而異於俗；弗知之者，異於義而同於俗。天下知之者少，則義非矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-14_p-3_s-1\",\n        \"han-fei-zi_ch-14_p-3_s-2\",\n        \"han-fei-zi_ch-14_p-3_s-3\",\n        \"han-fei-zi_ch-14_p-3_s-4\",\n        \"han-fei-zi_ch-14_p-3_s-5\",\n        \"han-fei-zi_ch-14_p-3_s-6\",\n        \"han-fei-zi_ch-14_p-3_s-7\",\n        \"han-fei-zi_ch-14_p-3_s-8\",\n        \"han-fei-zi_ch-14_p-3_s-9\",\n        \"han-fei-zi_ch-14_p-3_s-10\",\n        \"han-fei-zi_ch-14_p-3_s-11\",\n        \"han-fei-zi_ch-14_p-3_s-12\",\n        \"han-fei-zi_ch-14_p-3_s-13\",\n        \"han-fei-zi_ch-14_p-3_s-14\",\n        \"han-fei-zi_ch-14_p-3_s-15\",\n        \"han-fei-zi_ch-14_p-3_s-16\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"再的人或事況且世的愚學，皆不知治亂的情，讘䛟多誦先古的書，以亂當世的治；智慮不足以避阱井的陷，又妄絕不是有督察權術的士。聽他的言的人或事危，用他的計的人或事亂，此亦愚的至大，而且患的至甚的人或事啊。俱與有督察權術的士，有談說的名，而且實相去千萬啊，此夫名同而且實有異的人或事啊。夫世愚學的人比有督察權術的士啊，猶螘垤的比大陵啊，他的相去遠矣。而且聖人的人或事，審於是絕不是的實，察於治亂的情啊。所以他的治國啊，正明法規法令，陳嚴刑，將以救羣生的亂，去天下的禍，使強不陵弱，眾不暴寡，耆老得遂，幼孤得長，邊境不侵，國君臣屬相親，父子相保，而且無死亡係虜的患，此亦功的至厚的人或事啊。愚人不知，顧以為暴。愚的人或事固欲治而且惡他的所以治，皆惡危而且喜他的所以危的人或事。何以知的？夫嚴刑重刑罰的人或事，民的所惡啊，而且國的所以治啊；哀憐百姓、輕刑刑罰的人或事，民的所喜，而且國的所以危啊。聖人為法規法令國的人或事，必逆於世，而且順於道德。知的的人或事，同於義而且異於俗；弗知的的人或事，異於義而且同於俗。天下知的的人或事少，則義絕不是矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈奸劫弒臣〉。韓非深刻融合法、術、勢三大治國精要，此處「且夫世之愚學，皆不知治亂之情，讘䛟多誦先古之書，以亂當世之治」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「且」、「世」、「愚」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「且夫世之愚學皆不知治亂之情讘䛟多誦先古之書以亂當」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「智慮不足以避阱井之陷，又妄非有術之士」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"order\": 4,\n      \"canonicalText\": \"處非道之位，被眾口之譖，溺於當世之言，而欲當嚴天子而求安，幾不亦難哉！此夫智士所以至死而不顯於世者也。楚莊王之弟春申君有愛妾曰餘，春申君之正妻子曰甲，餘欲君之棄其妻也，因自傷其身以視君而泣，曰：「得為君之妾，甚幸。雖然，適夫人非所以事君也，適君非所以事夫人也。身故不肖，力不足以適二主，其勢不俱適，與其死夫人所者，不若賜死君前。妾以賜死，若復幸於左右，願君必察之，無為人笑。」君因信妾餘之詐，為棄正妻。餘又欲殺甲而以其子為後，因自裂其親身衣之，以示君而泣，曰：「餘之得幸君之日久矣，甲非弗知也，今乃欲強戲餘，餘與爭之，至裂餘之衣，而此子之不孝，莫大於此矣。」君怒，而殺甲也。故妻以妾餘之詐棄，而子以之死。從是觀之，父之愛子也，猶可以毀而害也。君臣之相與也，非有父子之親也，而群臣之毀言非特一妾之口也，何怪夫賢聖之戮死哉！此商君之所以車裂於秦，而吳起之所以枝解於楚者也。凡人臣者，有罪固不欲誅，無功者皆欲尊顯。而聖人之治國也，賞不加於無功，而誅必行於有罪者也。然則有術數者之為人也，固左右姦臣之所害，非明主弗能聽也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-14_p-4_s-1\",\n        \"han-fei-zi_ch-14_p-4_s-2\",\n        \"han-fei-zi_ch-14_p-4_s-3\",\n        \"han-fei-zi_ch-14_p-4_s-4\",\n        \"han-fei-zi_ch-14_p-4_s-5\",\n        \"han-fei-zi_ch-14_p-4_s-6\",\n        \"han-fei-zi_ch-14_p-4_s-7\",\n        \"han-fei-zi_ch-14_p-4_s-8\",\n        \"han-fei-zi_ch-14_p-4_s-9\",\n        \"han-fei-zi_ch-14_p-4_s-10\",\n        \"han-fei-zi_ch-14_p-4_s-11\",\n        \"han-fei-zi_ch-14_p-4_s-12\",\n        \"han-fei-zi_ch-14_p-4_s-13\",\n        \"han-fei-zi_ch-14_p-4_s-14\",\n        \"han-fei-zi_ch-14_p-4_s-15\",\n        \"han-fei-zi_ch-14_p-4_s-16\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"處絕不是道的位，被眾口的譖，溺於當世的言，而且欲當嚴天子而且求安，幾不亦難哉！此夫智士所以至死而且不顯於世的人或事啊。楚莊王的弟春申國君有愛妾說道：餘，春申國君的正妻子說道：甲，餘欲國君的棄他的妻啊，因自傷他的身以視國君而且泣，說道：得為國君的妾，甚幸。雖然，適夫人絕不是所以事國君啊，適國君絕不是所以事夫人啊。身所以不肖，力不足以適二主，他的權位威勢不俱適，與他的死夫人所的人或事，不若賜死國君前。妾以賜死，若復幸於左右，願國君必察的，無為人笑。國君因信妾餘的詐，為棄正妻。餘又欲殺甲而且以他的子為後，因自裂他的親身衣的，以示國君而且泣，說道：餘的得幸國君的日久矣，甲絕不是弗知啊，今乃欲強戲餘，餘與爭的，至裂餘的衣，而且此子的不孝，莫大於此矣。國君怒，而且殺甲啊。所以妻以妾餘的詐棄，而且子以的死。從是觀的，父的愛子啊，猶可以毀而且害啊。國君臣屬的相與啊，絕不是有父子的親啊，而且群臣屬的毀言絕不是特一妾的口啊，何怪夫賢聖的戮死哉！此商國君的所以車裂於秦，而且吳起的所以枝解於楚的人或事啊。凡人臣屬的人或事，有罪固不欲誅，無功的人或事皆欲尊顯。而且聖人的治國啊，賞賜不加於無功，而且誅必行於有罪的人或事啊。然則有督察權術數的人或事的為人啊，固左右姦臣屬的所害，絕不是明主弗能聽啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈奸劫弒臣〉。韓非深刻融合法、術、勢三大治國精要，此處「處非道之位，被眾口之譖，溺於當世之言，而欲當嚴天子而求安，幾不亦難哉」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「處」、「道」、「位」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「處非道之位被眾口之譖溺於當世之言而欲當嚴天子而求」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「此夫智士所以至死而不顯於世者也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"order\": 5,\n      \"canonicalText\": \"世之學術者說人主，不曰「乘威嚴之勢以困姦邪之臣」，而皆曰「仁義惠愛而已矣」。世主美仁義之名而不察其實，是以大者國亡身死，小者地削主卑。何以明之？夫施與貧困者，此世之所謂仁義；哀憐百姓不忍誅罰者，此世之所謂惠愛也。夫有施與貧困，則無功者得賞；不忍誅罰，則暴亂者不止。國有無功得賞者，則民不外務當敵斬首，內不急力田疾作，皆欲行貨財、事富貴、為私善、立名譽以取尊官厚俸。故姦私之臣愈眾，而暴亂之徒愈勝，不亡何待？夫嚴刑者，民之所畏也；重罰者，民之所惡也。故聖人陳其所畏以禁其邪，設其所惡以防其姦。是以國安而暴亂不起。吾以是明仁義愛惠之不足用，而嚴刑重罰之可以治國也。無捶策之威，銜橛之備，雖造父不能以服馬。無規矩之法，繩墨之端，雖王爾不能以成方圓。無威嚴之勢，賞罰之法，雖堯、舜不能以為治。今世主皆輕釋重罰、嚴誅，行愛惠，而欲霸王之功，亦不可幾也。故善為主者，明賞設利以勸之，使民以功賞，而不以仁義賜；嚴刑重罰以禁之，使民以罪誅而不以愛惠免。是以無功者不望，而有罪者不幸矣。託於犀車良馬之上，則可以陸犯阪阻之患；乘舟之安，持楫之利，則可以水絕江河之難；操法術之數，行重罰嚴誅，則可以致霸王之功。治國之有法術賞罰，猶若陸行之有犀車良馬也，水行之有輕舟便楫也，乘之者遂得其成。伊尹得之湯以王，管仲得之齊以霸，商君得之秦以強。此三人者，皆明於霸王之術，察於治強之數，而不以牽於世俗之言；適當世明主之意，則有直任布衣之士，立為卿相之處；處位治國，則有尊主廣地之實；此之謂足貴之臣。湯得伊尹，以百里之地立為天子；桓公得管仲，立為五霸主，九合諸侯，一匡天下；孝公得商君，地以廣，兵以強。故有忠臣者，外無敵國之患，內無亂臣之憂，長安於天下，而名垂後世，所謂忠臣也。若夫豫讓為智伯臣也，上不能說人主使之明法術、度數之理，以避禍難之患，下不能領御其眾，以安其國；及襄子之殺智伯也，豫讓乃自黔劓，敗其形容，以為智伯報襄子之仇；是雖有殘刑殺身以為人主之名，而實無益於智伯若秋毫之末。此吾之所下也，而世主以為忠而高之。古有伯夷、叔齊者，武王讓以天下而弗受，二人餓死首陽之陵；若此臣者，不畏重誅，不利重賞，不可以罰禁也，不可以賞使也。此之謂無益之臣也，吾所少而去也，而世主之所多而求也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-14_p-5_s-1\",\n        \"han-fei-zi_ch-14_p-5_s-2\",\n        \"han-fei-zi_ch-14_p-5_s-3\",\n        \"han-fei-zi_ch-14_p-5_s-4\",\n        \"han-fei-zi_ch-14_p-5_s-5\",\n        \"han-fei-zi_ch-14_p-5_s-6\",\n        \"han-fei-zi_ch-14_p-5_s-7\",\n        \"han-fei-zi_ch-14_p-5_s-8\",\n        \"han-fei-zi_ch-14_p-5_s-9\",\n        \"han-fei-zi_ch-14_p-5_s-10\",\n        \"han-fei-zi_ch-14_p-5_s-11\",\n        \"han-fei-zi_ch-14_p-5_s-12\",\n        \"han-fei-zi_ch-14_p-5_s-13\",\n        \"han-fei-zi_ch-14_p-5_s-14\",\n        \"han-fei-zi_ch-14_p-5_s-15\",\n        \"han-fei-zi_ch-14_p-5_s-16\",\n        \"han-fei-zi_ch-14_p-5_s-17\",\n        \"han-fei-zi_ch-14_p-5_s-18\",\n        \"han-fei-zi_ch-14_p-5_s-19\",\n        \"han-fei-zi_ch-14_p-5_s-20\",\n        \"han-fei-zi_ch-14_p-5_s-21\",\n        \"han-fei-zi_ch-14_p-5_s-22\",\n        \"han-fei-zi_ch-14_p-5_s-23\",\n        \"han-fei-zi_ch-14_p-5_s-24\",\n        \"han-fei-zi_ch-14_p-5_s-25\",\n        \"han-fei-zi_ch-14_p-5_s-26\",\n        \"han-fei-zi_ch-14_p-5_s-27\",\n        \"han-fei-zi_ch-14_p-5_s-28\",\n        \"han-fei-zi_ch-14_p-5_s-29\",\n        \"han-fei-zi_ch-14_p-5_s-30\",\n        \"han-fei-zi_ch-14_p-5_s-31\",\n        \"han-fei-zi_ch-14_p-5_s-32\",\n        \"han-fei-zi_ch-14_p-5_s-33\",\n        \"han-fei-zi_ch-14_p-5_s-34\",\n        \"han-fei-zi_ch-14_p-5_s-35\",\n        \"han-fei-zi_ch-14_p-5_s-36\",\n        \"han-fei-zi_ch-14_p-5_s-37\",\n        \"han-fei-zi_ch-14_p-5_s-38\",\n        \"han-fei-zi_ch-14_p-5_s-39\",\n        \"han-fei-zi_ch-14_p-5_s-40\",\n        \"han-fei-zi_ch-14_p-5_s-41\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"世的學督察權術的人或事說人主，不說道：乘威嚴的權位威勢以困姦邪的臣屬，而且皆說道：仁義惠愛而且已矣。世主美仁義的名而且不察他的實，是以大的人或事國亡身死，小的人或事地削主卑。何以明的？夫施與貧困的人或事，此世的所謂仁義；哀憐百姓不忍誅刑罰的人或事，此世的所謂惠愛啊。夫有施與貧困，則無功的人或事得賞賜；不忍誅刑罰，則暴亂的人或事不止。國有無功得賞賜的人或事，則民不外務當敵斬首，內不急力田疾作，皆欲行貨財、事富貴、為私善、立名譽以取尊官厚俸。所以姦私的臣屬愈眾，而且暴亂的徒愈勝，不亡何待？夫嚴刑的人或事，民的所畏啊；重刑罰的人或事，民的所惡啊。所以聖人陳他的所畏以禁他的邪，設他的所惡以防他的姦。是以國安而且暴亂不起。吾以是明仁義愛惠的不足用，而且嚴刑重刑罰的可以治國啊。無捶策的威，銜橛的備，雖造父不能以服馬。無規矩的法規法令，繩墨的端，雖王爾不能以成方圓。無威嚴的權位威勢，賞賜與刑罰的法規法令，雖堯、舜不能以為治。今世主皆輕釋重刑罰、嚴誅，行愛惠，而且欲霸王的功，亦不可幾啊。所以善為主的人或事，明賞賜設利以勸的，使民以功賞賜，而且不以仁義賜；嚴刑重刑罰以禁的，使民以罪誅而且不以愛惠免。是以無功的人或事不望，而且有罪的人或事不幸矣。託於犀車良馬的上，則可以陸犯阪阻的患；乘舟的安，持楫的利，則可以水絕江河的難；操法規法令督察權術的數，行重刑罰嚴誅，則可以致霸王的功。治國的有法規法令督察權術賞賜與刑罰，猶若陸行的有犀車良馬啊，水行的有輕舟便楫啊，乘的的人或事遂得他的成。伊尹得的湯以王，管仲得的齊以霸，商國君得的秦以強。此三人的人或事，皆明於霸王的督察權術，察於治強的數，而且不以牽於世俗的言；適當世明主的意，則有直任布衣的士，立為卿相的處；處位治國，則有尊主廣地的實；此的謂足貴的臣屬。湯得伊尹，以百里的地立為天子；桓公得管仲，立為五霸主，九合諸侯，一匡天下；孝公得商國君，地以廣，兵以強。所以有忠臣屬的人或事，外無敵國的患，內無亂臣屬的憂，長安於天下，而且名垂後世，所謂忠臣屬啊。至於談到那豫讓為智伯臣屬啊，上不能說人主使的明法規法令督察權術、度數的理，以避禍難的患，下不能領御他的眾，以安他的國；及襄子的殺智伯啊，豫讓乃自黔劓，敗他的形容，以為智伯報襄子的仇；是雖有殘刑殺身以為人主的名，而且實無益於智伯若秋毫的末。此吾的所下啊，而且世主以為忠而且高的。古有伯夷、叔齊的人或事，武王讓以天下而且弗受，二人餓死首陽的陵；若此臣屬的人或事，不畏重誅，不利重賞賜，不可以刑罰禁啊，不可以賞賜使啊。此的謂無益的臣屬啊，吾所少而且去啊，而且世主的所多而且求啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈奸劫弒臣〉。韓非深刻融合法、術、勢三大治國精要，此處「世之學術者說人主，不曰「乘威嚴之勢以困姦邪之臣」，而皆曰「仁義惠愛而已矣」」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「世」、「學」、「術」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「世之學術者說人主不曰乘威嚴之勢以困姦邪之臣而皆曰」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「世主美仁義之名而不察其實，是以大者國亡身死，小者地削主卑」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"order\": 6,\n      \"canonicalText\": \"諺曰：「厲憐王。」此不恭之言也。雖然，古無虛諺，不可不察也。此謂劫殺死亡之主言也。人主無法術以御其臣，雖長年而美材，大臣猶將得勢擅事主斷，而各為其私急。而恐父兄豪傑之士，借人主之力，以禁誅於己也，故弒賢長而立幼弱，廢正的而立不義。故春秋記之曰：「楚王子圍將聘於鄭，未出境，聞王病而反，因入問病，以其冠纓絞王而殺之，遂自立也。齊崔杼，其妻美，而莊公通之，數如崔氏之室，及公往，崔子之徒賈舉率崔子之徒而攻公，公入室，請與之分國，崔子不許，公請自刃於廟，崔子又不聽，公乃走踰於北牆，賈舉射公，中其股，公墜，崔子之徒以戈斫公而死之，而立其弟景公。」近之所見：李兌之用趙也，餓主父百日而死；卓齒之用齊也，擢湣王之筋，懸之廟梁，宿昔而死。故厲雖癰腫疕瘍，上比於春秋，未至於絞頸射股也；下比於近世，未至餓死擢筋也。故劫殺死亡之君，此其心之憂懼、形之苦痛也，必甚於厲矣。由此觀之，雖「厲憐王」可也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-14_p-6_s-1\",\n        \"han-fei-zi_ch-14_p-6_s-2\",\n        \"han-fei-zi_ch-14_p-6_s-3\",\n        \"han-fei-zi_ch-14_p-6_s-4\",\n        \"han-fei-zi_ch-14_p-6_s-5\",\n        \"han-fei-zi_ch-14_p-6_s-6\",\n        \"han-fei-zi_ch-14_p-6_s-7\",\n        \"han-fei-zi_ch-14_p-6_s-8\",\n        \"han-fei-zi_ch-14_p-6_s-9\",\n        \"han-fei-zi_ch-14_p-6_s-10\",\n        \"han-fei-zi_ch-14_p-6_s-11\",\n        \"han-fei-zi_ch-14_p-6_s-12\",\n        \"han-fei-zi_ch-14_p-6_s-13\",\n        \"han-fei-zi_ch-14_p-6_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"諺說道：厲憐王。此不恭的言啊。雖然，古無虛諺，不可不察啊。此謂劫殺死亡的主言啊。人主無法規法令督察權術以御他的臣屬，雖長年而且美材，大臣屬猶將得權位威勢擅事主斷，而且各為他的私急。而且恐父兄豪傑的士，借人主的力，以禁誅於己啊，所以弒賢長而且立幼弱，廢正的而且立不義。所以春秋記的說道：楚王子圍將聘於鄭，未出境，聞王病而且反，因入問病，以他的冠纓絞王而且殺的，遂自立啊。齊崔杼，他的妻美，而且莊公通的，數如崔氏的室，及公往，崔子的徒賈舉率崔子的徒而且攻公，公入室，請與的分國，崔子不許，公請自刃於廟，崔子又不聽，公乃走踰於北牆，賈舉射公，中他的股，公墜，崔子的徒以戈斫公而且死的，而且立他的弟景公。近的所見：李兌的用趙啊，餓主父百日而且死；卓齒的用齊啊，擢湣王的筋，懸的廟梁，宿昔而且死。所以厲雖癰腫疕瘍，上比於春秋，未至於絞頸射股啊；下比於近世，未至餓死擢筋啊。所以劫殺死亡的國君，此他的心的憂懼、形的苦痛啊，必甚於厲矣。由此觀的，雖厲憐王可啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈奸劫弒臣〉。韓非深刻融合法、術、勢三大治國精要，此處「諺曰：「厲憐王」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「諺」、「厲」、「憐」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「諺曰厲憐王此不恭之言也雖然古無虛諺不可不察也此謂」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」此不恭之言也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"凡姦臣皆欲順人主之心以取親幸之勢者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"是以主有所善，臣從而譽之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"主有所憎，臣因而毀之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"凡人之大體，取捨同者則相是也，取捨異者則相非也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"今人臣之所譽者，人主之所是也，此之謂同取。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"人臣之所毀者，人主之所非也，此之謂同舍。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"夫取捨合而相與逆者，未嘗聞也，此人臣之所以取信幸之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"夫姦臣得乘信幸之勢以毀譽進退群臣者，人主非有術數以御之也，非參驗以審之也，必將以曩之合己信今之言，此倖臣之所以得欺主成私者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"故主必欺於上，而臣必重於下矣，此之謂擅主之臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"國有擅主之臣，則羣下不得盡其智力以陳其忠，百官之吏不得奉法以致其功矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 11,\n      \"canonicalText\": \"何以明之？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 12,\n      \"canonicalText\": \"夫安利者就之，危害者去之，此人之情也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 13,\n      \"canonicalText\": \"今為臣盡力以致功，竭智以陳忠者，其身困而家貧，父子罹其害；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 14,\n      \"canonicalText\": \"為姦利以弊人主，行財貨以事貴重之臣者，身尊家富，父子被其澤；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 15,\n      \"canonicalText\": \"人焉能去安利之道而就危害之處哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 16,\n      \"canonicalText\": \"治國若此其過也，而上欲下之無姦，吏之奉法，其不可得亦明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 17,\n      \"canonicalText\": \"故左右知貞信之不可以得安利也，必曰：「我以忠信事上積功勞而求安，是猶盲而欲知黑白之情，必不幾矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 18,\n      \"canonicalText\": \"若以道化行正理不趨富貴事上而求安，是猶聾而欲審清濁之聲也，愈不幾矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 19,\n      \"canonicalText\": \"二者不可以得安，我安能無相比周、蔽主上、為姦私以適重人哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 20,\n      \"canonicalText\": \"」此必不顧人主之義矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 21,\n      \"canonicalText\": \"其百官之吏，亦知方正之不可以得安也，必曰：「我以清廉事上而求安，若無規矩而欲為方圓也，必不幾矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 22,\n      \"canonicalText\": \"若以守法不朋黨治官而求安，是猶以足搔頂也，愈不幾也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-23\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 23,\n      \"canonicalText\": \"二者不可以得安，能無廢法行私以適重人哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-24\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 24,\n      \"canonicalText\": \"」此必不顧君上之法矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-25\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 25,\n      \"canonicalText\": \"故以私為重人者眾，而以法事君者少矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-1_s-26\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-1\",\n      \"order\": 26,\n      \"canonicalText\": \"是以主孤於上而臣成黨於下，此田成之所以弒簡公者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"夫有術者之為人臣也，得效度數之言，上明主法，下困姦臣，以尊主安國者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"是以度數之言得效於前，則賞罰必用於後矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"人主誠明於聖人之術，而不苟於世俗之言，循名實而定是非，因參驗而審言辭。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"是以左右近習之臣，知偽詐之不可以得安也，必曰：「我不去姦私之行盡力竭智以事主，而乃以相與比周妄毀譽以求安，是猶負千鈞之重，陷於不測之淵而求生也，必不幾矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"」百官之吏，亦知為姦利之不可以得安也，必曰：「我不以清廉方正奉法，乃以貪污之心枉法以取私利，是猶上高陵之顛，墮峻谿之下而求生，必不幾矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"」安危之道若此其明也，左右安能以虛言惑主，而百官安敢以貪漁下？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"是以臣得陳其忠而不弊，下得守其職而不怨。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"此管仲之所以治齊，而商君之所以強秦也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 9,\n      \"canonicalText\": \"從是觀之，則聖人之治國也，固有使人不得不愛我之道，而不恃人之以愛為我也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 10,\n      \"canonicalText\": \"恃人之以愛為我者危矣，恃吾不可不為者安矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 11,\n      \"canonicalText\": \"夫君臣非有骨肉之親，正直之道可以得利，則臣盡力以事主；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 12,\n      \"canonicalText\": \"正直之道不可以得安，則臣行私以幹上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 13,\n      \"canonicalText\": \"明主知之，故設利害之道以示天下而已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 14,\n      \"canonicalText\": \"夫是以人主雖不口教百官，不目索姦邪，而國已治矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 15,\n      \"canonicalText\": \"人主者，非目若離婁乃為明也，非耳若師曠乃為聰也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 16,\n      \"canonicalText\": \"目必，不任其數，而待目以為明，所見者少矣，非不弊之術也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 17,\n      \"canonicalText\": \"耳必，不因其勢，而待耳以為聰，所聞者寡矣，非不欺之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 18,\n      \"canonicalText\": \"明主者，使天下不得不為己視，天下不得不為己聽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 19,\n      \"canonicalText\": \"故身在深宮之中而明照四海之內，而天下弗能蔽、弗能欺者何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 20,\n      \"canonicalText\": \"闇亂之道廢，而聰明之勢興也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 21,\n      \"canonicalText\": \"故善任勢者國安，不知因其勢者國危。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 22,\n      \"canonicalText\": \"古秦之俗，君臣廢法而服私，是以國亂兵弱而主卑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-23\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 23,\n      \"canonicalText\": \"商君說秦孝公以變法易俗而明公道，賞告姦，困末作而利本事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-24\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 24,\n      \"canonicalText\": \"當此之時，秦民習故俗之有罪可以得免、無功可以得尊顯也，故輕犯新法。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-25\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 25,\n      \"canonicalText\": \"於是犯之者其誅重而必，告之者其賞厚而信，故姦莫不得而被刑者眾，民疾怨而眾過日聞。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-26\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 26,\n      \"canonicalText\": \"孝公不聽，遂行商君之法，民後知有罪之必誅，而私姦者眾也，故民莫犯，其刑無所加。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-27\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 27,\n      \"canonicalText\": \"是以國治而兵強，地廣而主尊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-28\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 28,\n      \"canonicalText\": \"此其所以然者，匿罪之罰重，而告姦之賞厚也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-29\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 29,\n      \"canonicalText\": \"此亦使天下必為己視聽之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-2_s-30\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-2\",\n      \"order\": 30,\n      \"canonicalText\": \"至治之法術已明矣，而世學者弗知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"且夫世之愚學，皆不知治亂之情，讘䛟多誦先古之書，以亂當世之治；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"智慮不足以避阱井之陷，又妄非有術之士。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"聽其言者危，用其計者亂，此亦愚之至大，而患之至甚者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"俱與有術之士，有談說之名，而實相去千萬也，此夫名同而實有異者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"夫世愚學之人比有術之士也，猶螘垤之比大陵也，其相去遠矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"而聖人者，審於是非之實，察於治亂之情也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"故其治國也，正明法，陳嚴刑，將以救羣生之亂，去天下之禍，使強不陵弱，眾不暴寡，耆老得遂，幼孤得長，邊境不侵，君臣相親，父子相保，而無死亡係虜之患，此亦功之至厚者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"愚人不知，顧以為暴。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"愚者固欲治而惡其所以治，皆惡危而喜其所以危者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 10,\n      \"canonicalText\": \"何以知之？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 11,\n      \"canonicalText\": \"夫嚴刑重罰者，民之所惡也，而國之所以治也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 12,\n      \"canonicalText\": \"哀憐百姓、輕刑罰者，民之所喜，而國之所以危也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 13,\n      \"canonicalText\": \"聖人為法國者，必逆於世，而順於道德。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 14,\n      \"canonicalText\": \"知之者，同於義而異於俗；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 15,\n      \"canonicalText\": \"弗知之者，異於義而同於俗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-3_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-3\",\n      \"order\": 16,\n      \"canonicalText\": \"天下知之者少，則義非矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"處非道之位，被眾口之譖，溺於當世之言，而欲當嚴天子而求安，幾不亦難哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"此夫智士所以至死而不顯於世者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"楚莊王之弟春申君有愛妾曰餘，春申君之正妻子曰甲，餘欲君之棄其妻也，因自傷其身以視君而泣，曰：「得為君之妾，甚幸。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"雖然，適夫人非所以事君也，適君非所以事夫人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"身故不肖，力不足以適二主，其勢不俱適，與其死夫人所者，不若賜死君前。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"妾以賜死，若復幸於左右，願君必察之，無為人笑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"」君因信妾餘之詐，為棄正妻。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"餘又欲殺甲而以其子為後，因自裂其親身衣之，以示君而泣，曰：「餘之得幸君之日久矣，甲非弗知也，今乃欲強戲餘，餘與爭之，至裂餘之衣，而此子之不孝，莫大於此矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"」君怒，而殺甲也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"故妻以妾餘之詐棄，而子以之死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"從是觀之，父之愛子也，猶可以毀而害也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 12,\n      \"canonicalText\": \"君臣之相與也，非有父子之親也，而群臣之毀言非特一妾之口也，何怪夫賢聖之戮死哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 13,\n      \"canonicalText\": \"此商君之所以車裂於秦，而吳起之所以枝解於楚者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 14,\n      \"canonicalText\": \"凡人臣者，有罪固不欲誅，無功者皆欲尊顯。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 15,\n      \"canonicalText\": \"而聖人之治國也，賞不加於無功，而誅必行於有罪者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-4_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-4\",\n      \"order\": 16,\n      \"canonicalText\": \"然則有術數者之為人也，固左右姦臣之所害，非明主弗能聽也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"世之學術者說人主，不曰「乘威嚴之勢以困姦邪之臣」，而皆曰「仁義惠愛而已矣」。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"世主美仁義之名而不察其實，是以大者國亡身死，小者地削主卑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"何以明之？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"夫施與貧困者，此世之所謂仁義；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"哀憐百姓不忍誅罰者，此世之所謂惠愛也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"夫有施與貧困，則無功者得賞；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"不忍誅罰，則暴亂者不止。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"國有無功得賞者，則民不外務當敵斬首，內不急力田疾作，皆欲行貨財、事富貴、為私善、立名譽以取尊官厚俸。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"故姦私之臣愈眾，而暴亂之徒愈勝，不亡何待？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"夫嚴刑者，民之所畏也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"重罰者，民之所惡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"故聖人陳其所畏以禁其邪，設其所惡以防其姦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"是以國安而暴亂不起。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 14,\n      \"canonicalText\": \"吾以是明仁義愛惠之不足用，而嚴刑重罰之可以治國也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 15,\n      \"canonicalText\": \"無捶策之威，銜橛之備，雖造父不能以服馬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 16,\n      \"canonicalText\": \"無規矩之法，繩墨之端，雖王爾不能以成方圓。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 17,\n      \"canonicalText\": \"無威嚴之勢，賞罰之法，雖堯、舜不能以為治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 18,\n      \"canonicalText\": \"今世主皆輕釋重罰、嚴誅，行愛惠，而欲霸王之功，亦不可幾也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 19,\n      \"canonicalText\": \"故善為主者，明賞設利以勸之，使民以功賞，而不以仁義賜；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 20,\n      \"canonicalText\": \"嚴刑重罰以禁之，使民以罪誅而不以愛惠免。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 21,\n      \"canonicalText\": \"是以無功者不望，而有罪者不幸矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 22,\n      \"canonicalText\": \"託於犀車良馬之上，則可以陸犯阪阻之患；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-23\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 23,\n      \"canonicalText\": \"乘舟之安，持楫之利，則可以水絕江河之難；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-24\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 24,\n      \"canonicalText\": \"操法術之數，行重罰嚴誅，則可以致霸王之功。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-25\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 25,\n      \"canonicalText\": \"治國之有法術賞罰，猶若陸行之有犀車良馬也，水行之有輕舟便楫也，乘之者遂得其成。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-26\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 26,\n      \"canonicalText\": \"伊尹得之湯以王，管仲得之齊以霸，商君得之秦以強。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-27\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 27,\n      \"canonicalText\": \"此三人者，皆明於霸王之術，察於治強之數，而不以牽於世俗之言；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-28\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 28,\n      \"canonicalText\": \"適當世明主之意，則有直任布衣之士，立為卿相之處；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-29\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 29,\n      \"canonicalText\": \"處位治國，則有尊主廣地之實；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-30\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 30,\n      \"canonicalText\": \"此之謂足貴之臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-31\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 31,\n      \"canonicalText\": \"湯得伊尹，以百里之地立為天子；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-32\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 32,\n      \"canonicalText\": \"桓公得管仲，立為五霸主，九合諸侯，一匡天下；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-33\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 33,\n      \"canonicalText\": \"孝公得商君，地以廣，兵以強。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-34\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 34,\n      \"canonicalText\": \"故有忠臣者，外無敵國之患，內無亂臣之憂，長安於天下，而名垂後世，所謂忠臣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-35\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 35,\n      \"canonicalText\": \"若夫豫讓為智伯臣也，上不能說人主使之明法術、度數之理，以避禍難之患，下不能領御其眾，以安其國；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-36\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 36,\n      \"canonicalText\": \"及襄子之殺智伯也，豫讓乃自黔劓，敗其形容，以為智伯報襄子之仇；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-37\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 37,\n      \"canonicalText\": \"是雖有殘刑殺身以為人主之名，而實無益於智伯若秋毫之末。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-38\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 38,\n      \"canonicalText\": \"此吾之所下也，而世主以為忠而高之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-39\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 39,\n      \"canonicalText\": \"古有伯夷、叔齊者，武王讓以天下而弗受，二人餓死首陽之陵；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-40\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 40,\n      \"canonicalText\": \"若此臣者，不畏重誅，不利重賞，不可以罰禁也，不可以賞使也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-5_s-41\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-5\",\n      \"order\": 41,\n      \"canonicalText\": \"此之謂無益之臣也，吾所少而去也，而世主之所多而求也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"諺曰：「厲憐王。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"」此不恭之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"雖然，古無虛諺，不可不察也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"此謂劫殺死亡之主言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"人主無法術以御其臣，雖長年而美材，大臣猶將得勢擅事主斷，而各為其私急。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"而恐父兄豪傑之士，借人主之力，以禁誅於己也，故弒賢長而立幼弱，廢正的而立不義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"故春秋記之曰：「楚王子圍將聘於鄭，未出境，聞王病而反，因入問病，以其冠纓絞王而殺之，遂自立也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"齊崔杼，其妻美，而莊公通之，數如崔氏之室，及公往，崔子之徒賈舉率崔子之徒而攻公，公入室，請與之分國，崔子不許，公請自刃於廟，崔子又不聽，公乃走踰於北牆，賈舉射公，中其股，公墜，崔子之徒以戈斫公而死之，而立其弟景公。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"」近之所見：李兌之用趙也，餓主父百日而死；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"卓齒之用齊也，擢湣王之筋，懸之廟梁，宿昔而死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"故厲雖癰腫疕瘍，上比於春秋，未至於絞頸射股也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"下比於近世，未至餓死擢筋也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 13,\n      \"canonicalText\": \"故劫殺死亡之君，此其心之憂懼、形之苦痛也，必甚於厲矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-14_p-6_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-14\",\n      \"passageId\": \"han-fei-zi_ch-14_p-6\",\n      \"order\": 14,\n      \"canonicalText\": \"由此觀之，雖「厲憐王」可也。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
